<template><div class="section"><FloatingActions/><div class="container contact-grid"><div><span class="kicker">CONTACT WON NYACI RUN</span><h1>Bring your idea to the movement.</h1><p class="section-lead">Sponsorship, group registrations, volunteering, media or general enquiries — send us a message and the admin team will receive it.</p><div class="culture-card"><h3>Run day</h3><p>24 October 2026 · Old Akii Bua Stadium, Lira</p><p>Registration & aerobics: 6:00 AM</p><p>Running: 7:30 AM</p></div></div><form class="contact-form" @submit.prevent="submit"><div v-if="success" class="success">{{success}}</div><div v-if="error" class="error">{{error}}</div><div class="field"><label>Name *</label><input v-model="form.name" required></div><div class="field"><label>Email *</label><input v-model="form.email" type="email" required></div><div class="field"><label>Phone</label><input v-model="form.phone"></div><div class="field"><label>Subject</label><input v-model="form.subject"></div><div class="field"><label>Message *</label><textarea v-model="form.message" rows="7" required></textarea></div><button class="btn btn-primary" :disabled="loading">{{loading?'Sending…':'Send message →'}}</button></form></div></div></template>
<script setup>import {reactive,ref} from 'vue';import axios from 'axios';import FloatingActions from '../components/FloatingActions.vue';const form=reactive({name:'',email:'',phone:'',subject:'',message:''}),loading=ref(false),success=ref(''),error=ref('');const submit=async()=>{loading.value=true;success.value='';error.value='';try{await axios.get('/api/csrf');const {data}=await axios.post('/api/contact',form);success.value=data.message;Object.assign(form,{name:'',email:'',phone:'',subject:'',message:''})}catch(e){error.value=e.response?.data?.message||'Could not send your message.'}finally{loading.value=false}}</script>
